module mux_synch (

input [7:0] data_in,   			//asynchronous data input
input req,                  		//indicating that data is available at the data_in input
input dst_clk,                 		//destination clock
input src_clk,                 		//source clock
input nrst,                    		//asynchronous reset 
output reg [7:0] data_out,              //synchronized version of data_in to the destination clock domain
output ack_out ); 		


wire syncd_req,anded_req,syncd_ack;
reg syncd_req_1,ack;


nff  req_synch_0 (.d_in(req),.dst_clk(dst_clk),.rst(nrst),.syncd(syncd_req)) ;		//2-flop synchronizer for the enable input


always_ff @(posedge dst_clk or negedge nrst) 					//one clock cycle delayed synced_enable
begin
    if(!nrst)syncd_req_1<=0;else syncd_req_1 <= syncd_req;
end

assign anded_req = (!syncd_req_1 && syncd_req);    					//posedge detector


always_ff @(posedge dst_clk or negedge nrst)
begin                                                   
	if(!nrst)
		data_out <= 1'b0;               					//forcing the output data_in to zero when an active-low asynchronous reset is detected.

	else if (anded_req==1'b1)
		data_out <= data_in;                    				//latching data_in to data_out when the enable signal is available.

	else
		data_out <= data_out;                   				//holds the data till next req comes.
end


// acknowledgment signal generation
always_ff@(posedge dst_clk or negedge nrst)
begin
	if(!nrst)
		ack <= 1'b0; 

	else if (anded_req==1'b1)
		ack <= 1'b1;

	else if(!syncd_req)
		ack <= 1'b0;
end

//changing the clock domain of the ack signal
nff  enable_synch_1 (.d_in(ack),.dst_clk(src_clk),.rst(nrst),.syncd(syncd_ack)) ;

//edge detector circuit
assign ack_out = syncd_ack;


endmodule

module nff  (

	input d_in,   									//input data that needs to be synchronized to the dst_clk domain.
	input dst_clk,     								//destination domain clock.
	input rst,         								//asynchronous active-low reset
	output reg  syncd 								//synced output, which is a 2-clock-cycle delayed version of d_in.
	                   );

reg   dmeta;             								//register to hold output.



always@(posedge dst_clk or negedge rst)  
begin
	if(!rst)              								//active-low asynchronous reset
  begin
    syncd <= 1'b0;      								//resetting the synced register to 0
    dmeta <= 1'b0;      								//resetting dmeta register to 0
  end
  else
  begin
    dmeta <= d_in;      								//passing d_in to dmeta
    syncd <= dmeta;     								//passing dmeta to syncd
  end
end

endmodule

module sync_lifo #(parameter DATA_WIDTH=8,ADDR_WIDTH=3)(input clock,reset,write_en,read_en,input [DATA_WIDTH-1:0] data_in,output empty,full,output reg [DATA_WIDTH-1:0] data_out);
localparam DEPTH=1<<ADDR_WIDTH;reg [DATA_WIDTH-1:0] mem[0:DEPTH-1];reg [ADDR_WIDTH:0] count;integer i;
assign empty=count==0;assign full=count==DEPTH;
always @(posedge clock)if(reset)begin count<=0;data_out<=0;for(i=0;i<DEPTH;i=i+1)mem[i]<=0;end
else if(write_en&&!full)begin mem[count]<=data_in;count<=count+1'b1;end
else if(read_en&&!empty)begin data_out<=mem[count-1];count<=count-1'b1;end endmodule

module crossbar_switch #(
    parameter DATA_WIDTH = 8,  // Parameterized data width
    localparam NUM_PORTS = 4,
    localparam DATA_WIDTH_IN = (DATA_WIDTH + $clog2(NUM_PORTS))
)(
    input  logic                        clk,        // Clock signal
    input  logic                        reset,      // Reset signal
    // Input data and destination IDs
    input  logic [DATA_WIDTH_IN-1 :0]  in0, in1, in2, in3,  // Input data
    input  logic                       valid_in0, valid_in1, valid_in2, valid_in3,  // Input data valid
    // Output data
    output logic  [DATA_WIDTH-1:0]      out0, out1, out2, out3,  // Output data
    output logic                        valid_out0, valid_out1, valid_out2, valid_out3  // Output data valid
);
    // Internal Signals
    logic [$clog2(NUM_PORTS)-1 : 0] dest0,dest1,dest2,dest3;           // Destination ID for each input

    // ----------------------------------------
    // - Procedural blocks
    // ----------------------------------------
    always @(posedge clk or negedge reset) begin
        if (!reset) begin
            out0 <= 0;
            out1 <= 0;
            out2 <= 0;
            out3 <= 0;
            valid_out0 <= 1'b0;
            valid_out1 <= 1'b0;
            valid_out2 <= 1'b0;
            valid_out3 <= 1'b0;
        end else begin
            out0 <= 0 ;
            out1 <= 0 ;
            out2 <= 0 ;
            out3 <= 0 ;
            valid_out0 <= 1'b0;
            valid_out1 <= 1'b0;
            valid_out2 <= 1'b0;
            valid_out3 <= 1'b0;

            if (valid_in0 == 1) begin

                    case(dest0)
0:begin out0<=in0[DATA_WIDTH-1:0];valid_out0<=1;end
1:begin out1<=in0[DATA_WIDTH-1:0];valid_out1<=1;end
2:begin out2<=in0[DATA_WIDTH-1:0];valid_out2<=1;end
3:begin out3<=in0[DATA_WIDTH-1:0];valid_out3<=1;end
endcase

            end else if (valid_in1 == 1) begin

                    case(dest1)
0:begin out0<=in1[DATA_WIDTH-1:0];valid_out0<=1;end
1:begin out1<=in1[DATA_WIDTH-1:0];valid_out1<=1;end
2:begin out2<=in1[DATA_WIDTH-1:0];valid_out2<=1;end
3:begin out3<=in1[DATA_WIDTH-1:0];valid_out3<=1;end
endcase

            end else if (valid_in2 == 1) begin

                    case(dest2)
0:begin out0<=in2[DATA_WIDTH-1:0];valid_out0<=1;end
1:begin out1<=in2[DATA_WIDTH-1:0];valid_out1<=1;end
2:begin out2<=in2[DATA_WIDTH-1:0];valid_out2<=1;end
3:begin out3<=in2[DATA_WIDTH-1:0];valid_out3<=1;end
endcase

            end else if (valid_in3 == 1) begin

                    case(dest3)
0:begin out0<=in3[DATA_WIDTH-1:0];valid_out0<=1;end
1:begin out1<=in3[DATA_WIDTH-1:0];valid_out1<=1;end
2:begin out2<=in3[DATA_WIDTH-1:0];valid_out2<=1;end
3:begin out3<=in3[DATA_WIDTH-1:0];valid_out3<=1;end
endcase

            end else begin
                out0 <= 0 ;
                out1 <= 0 ;
                out2 <= 0 ;
                out3 <= 0 ;
            end
        end
    end

    // ----------------------------------------
    // - Combinational Assignments
    // ----------------------------------------
    assign dest0 = in0 [DATA_WIDTH_IN-1 : DATA_WIDTH_IN-2] ; // Destination port ID for in0 data
    assign dest1 = in1 [DATA_WIDTH_IN-1 : DATA_WIDTH_IN-2] ; // Destination port ID for in1 data
    assign dest2 = in2 [DATA_WIDTH_IN-1 : DATA_WIDTH_IN-2] ; // Destination port ID for in2 data
    assign dest3 = in3 [DATA_WIDTH_IN-1 : DATA_WIDTH_IN-2] ; // Destination port ID for in3 data

endmodule

