module write_buffer_merge #(
  parameter INPUT_DATA_WIDTH  = 32,                                     // Width of input data
  parameter INPUT_ADDR_WIDTH  = 16,                                     // Width of input address
  parameter BUFFER_DEPTH      = 8,                                      // Depth of the write buffer
  parameter OUTPUT_DATA_WIDTH = INPUT_DATA_WIDTH * BUFFER_DEPTH,        // Width of merged output data
  parameter OUTPUT_ADDR_WIDTH = INPUT_ADDR_WIDTH - $clog2(BUFFER_DEPTH) // Width of merged output address
) (
  input  logic                         clk,          // Clock signal
  input  logic                         srst,         // Synchronous reset (active high)
  input  logic                         wr_en_in,     // Write enable input
  input  logic [INPUT_ADDR_WIDTH-1:0]  wr_addr_in,   // Write address input
  input  logic [INPUT_DATA_WIDTH-1:0]  wr_data_in,   // Write data input
  output logic                         wr_en_out,    // Write enable output
  output logic [OUTPUT_ADDR_WIDTH-1:0] wr_addr_out,  // Write address output
  output logic [OUTPUT_DATA_WIDTH-1:0] wr_data_out   // Write data output
);

  // Internal signals for buffer tracking and management
  logic [$clog2(BUFFER_DEPTH)-1:0]      write_count;     // Counter for the number of writes in the buffer
  logic [OUTPUT_ADDR_WIDTH-1:0]         base_addr;       // Base address for the merged writes
  logic [OUTPUT_DATA_WIDTH-1:0]         merged_data;     // Buffer to hold merged data
  logic                                 write_complete;  // Signal to indicate that the buffer is full and ready to output

  generate
    if (BUFFER_DEPTH > 1) begin
      // Write count logic: Counts the number of writes in the buffer
      always_ff @(posedge clk) begin
        if (srst) 
          write_count <= '0;
        else if (wr_en_in)
          write_count <= write_count + 1;  // Increment count on write enable
      end

      // Base address logic: Captures the address of the first write in the buffer
      always_ff @(posedge clk) begin
        if (srst)
          base_addr <= '0;
          else if(wr_en_in && write_count==0)base_addr<=wr_addr_in>>$clog2(BUFFER_DEPTH);
      end

      // Merged data logic: Concatenates incoming data into the buffer
      always_ff @(posedge clk) begin
        if (srst)
          merged_data <= '0;
        else if (wr_en_in)
          merged_data<={wr_data_in,merged_data[OUTPUT_DATA_WIDTH-1:INPUT_DATA_WIDTH]};
      end

      // Write completion logic: Indicates when the buffer is full
      always_ff @(posedge clk) begin
        if (srst)
          write_complete <= 1'b0;
        else if ((write_count == (BUFFER_DEPTH - 1)) && wr_en_in)
          write_complete <= 1'b1;  // Assert completion when buffer is full
        else
          write_complete <= 1'b0;
      end

      always_ff @(posedge clk)if(srst)begin wr_en_out<=0;wr_addr_out<=0;wr_data_out<=0;end else begin wr_en_out<=write_complete;if(write_complete)begin wr_addr_out<=base_addr;wr_data_out<=merged_data;end end

    end else begin

      always_ff @(posedge clk)if(srst)begin wr_en_out<=0;wr_addr_out<=0;wr_data_out<=0;end else begin wr_en_out<=wr_en_in;wr_addr_out<=wr_addr_in;wr_data_out<=wr_data_in;end

    end
  endgenerate

endmodule

module lru_counter_policy #(parameter NWAYS=4,NINDEXES=32)(input clock,reset,input [$clog2(NINDEXES)-1:0] index,input [$clog2(NWAYS)-1:0] way_select,input access,hit,output reg [$clog2(NWAYS)-1:0] way_replace);
localparam W=$clog2(NWAYS);reg [NWAYS*W-1:0] recency[0:NINDEXES-1];integer i,n;
wire [W-1:0] selected=hit?way_select:way_replace;
// Replacement: rank zero is least recently used.
always @*begin way_replace=0;for(integer j=0;j<NWAYS;j=j+1)if(recency[index][j*W+:W]==0)way_replace=j;end
// Recency update preserves unique ranks.
always @(posedge clock or posedge reset)if(reset)begin for(i=0;i<NINDEXES;i=i+1)for(n=0;n<NWAYS;n=n+1)recency[i][n*W+:W]<=n;end
else if(access)for(n=0;n<NWAYS;n=n+1)begin if(n==selected)recency[index][n*W+:W]<=NWAYS-1;else if(recency[index][n*W+:W]>recency[index][selected*W+:W])recency[index][n*W+:W]<=recency[index][n*W+:W]-1'b1;end endmodule

module virtual2physical_tlb #(parameter ADDR_WIDTH = 8, PAGE_WIDTH = 8, TLB_SIZE = 4, PAGE_TABLE_SIZE = 16) (
    input clk,
    input reset,
    input [ADDR_WIDTH-1:0] virtual_address,
    output [PAGE_WIDTH-1:0] physical_address,
    output hit, miss
);
    wire tlb_write_enable, flush, ready;
    wire [PAGE_WIDTH-1:0] page_table_entry;
    TLB #(.TLB_SIZE(TLB_SIZE), .ADDR_WIDTH(ADDR_WIDTH), .PAGE_WIDTH(PAGE_WIDTH)) tlb (
        .clk(clk),
        .reset(reset),
        .virtual_address(virtual_address),
        .tlb_write_enable(tlb_write_enable),
        .flush(flush),
        .page_table_entry(page_table_entry),
        .physical_address(physical_address),
        .hit(hit),
        .miss(miss)
    );

    PageTableHandler #(.ADDR_WIDTH(ADDR_WIDTH), .PAGE_WIDTH(PAGE_WIDTH), .PAGE_TABLE_SIZE(PAGE_TABLE_SIZE)) page_table_handler(
        .clk(clk),
        .reset(reset),
        .miss(miss),
        .virtual_page(virtual_address),
        .page_table_entry(page_table_entry),
        .ready(ready)
    );

    ControlUnit control_unit (
        .clk(clk),
        .reset(reset),
        .hit(hit),
        .miss(miss),
        .ready(ready),
        .tlb_write_enable(tlb_write_enable),
        .flush(flush)
    );
endmodule

module TLB #(parameter TLB_SIZE = 4, ADDR_WIDTH = 8, PAGE_WIDTH = 8) (
    input clk,
    input reset,
    input [ADDR_WIDTH-1:0] virtual_address,
    input tlb_write_enable,
    input flush,
    input [PAGE_WIDTH-1:0] page_table_entry,
    output reg [PAGE_WIDTH-1:0] physical_address,
    output reg hit,
    output reg miss
);
    // TLB Storage
    reg [ADDR_WIDTH-1:0] virtual_tags[TLB_SIZE-1:0];
    reg [PAGE_WIDTH-1:0] physical_pages[TLB_SIZE-1:0];
    reg [TLB_SIZE-1:0] valid_bits;
    reg [$clog2(TLB_SIZE)-1:0] replacement_index; // Index for the next replacement
    integer i;

    always @(posedge clk or posedge reset)begin
if(reset)begin valid_bits<=0;replacement_index<=0;for(integer j=0;j<TLB_SIZE;j=j+1)begin virtual_tags[j]<=0;physical_pages[j]<=0;end end
else if(flush)begin valid_bits<=0;replacement_index<=0;end
else if(miss)begin valid_bits[replacement_index]<=1;virtual_tags[replacement_index]<=virtual_address;physical_pages[replacement_index]<=page_table_entry;replacement_index<=replacement_index==TLB_SIZE-1?0:replacement_index+1'b1;end end

    always_comb begin
        hit = 0;
        miss = 1;
        physical_address = page_table_entry;

        for(integer j=0;j<TLB_SIZE;j=j+1)if(valid_bits[j] && virtual_tags[j]==virtual_address)begin hit=1;miss=0;physical_address=physical_pages[j];end

    end
endmodule

module PageTableHandler #(parameter ADDR_WIDTH = 8, PAGE_WIDTH = 8, PAGE_TABLE_SIZE = 16) (
    input clk,
    input reset,
    input miss,
    input [ADDR_WIDTH-1:0] virtual_page,
    output reg [PAGE_WIDTH-1:0] page_table_entry,
    output reg ready
);
    // Parameterized Page Table Memory
    reg [PAGE_WIDTH-1:0] page_table_memory [0:PAGE_TABLE_SIZE-1];
 assign   page_table_entry = page_table_memory[virtual_page];  
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Initialize Page Table Memory during reset
            page_table_memory[0] <= 8'h0;
            page_table_memory[1] <= 8'h1;
            page_table_memory[2] <= 8'h2;
            page_table_memory[3] <= 8'h3;  
            page_table_memory[4] <= 8'h4;
            page_table_memory[5] <= 8'h5;
            page_table_memory[6] <= 8'h6;
            page_table_memory[7] <= 8'h7;
            page_table_memory[8] <= 8'h8;  
            page_table_memory[9] <= 8'h9;
            page_table_memory[10] <= 8'hA;
            page_table_memory[11] <= 8'hB;  
            page_table_memory[12] <= 8'hC;
            page_table_memory[13] <= 8'hD;
            page_table_memory[14] <= 8'hE;
            page_table_memory[15] <= 8'hF;          
            ready = 0;
        end else if (miss) begin
            // Fetch the physical page number from the simulated page table         
            ready <= 1; // Indicate the entry is ready
        end else begin
            ready <= 0;
        end
    end
endmodule
module ControlUnit (
    input clk,
    input reset,
    input hit,
    input miss,
    input ready,
    output reg tlb_write_enable,
    output reg flush
);
    reg [1:0] state;

    localparam IDLE = 2'b00,
               FETCH = 2'b01,
               UPDATE = 2'b10;

always @(posedge clk or posedge reset)if(reset)begin state<=IDLE;tlb_write_enable<=0;flush<=0;end else begin tlb_write_enable<=0;flush<=0;case(state)
IDLE:if(miss)state<=FETCH;
FETCH:if(ready)begin tlb_write_enable<=1;state<=UPDATE;end
UPDATE:state<=IDLE;default:state<=IDLE;endcase end

endmodule

module instruction_cache_controller (
    input  wire        clk,                // Clock signal
    input  wire        rst,                // Reset signal

    output reg         io_mem_valid,       // Indicates that memory operation is valid
    input  wire        io_mem_ready,       // Indicates that memory is ready for the operation
    output reg  [16:0] io_mem_addr,        // Address for memory operation

    output reg         l1b_wait,           // Indicates if the L1 cache is still waiting for data
    output wire [31:0] l1b_data,           // Data output from the L1 cache
    input  wire [17:0] l1b_addr,           // Address of the L1 cache (18-bits)

    // RAM256_T0 (Tag Memory 0)
    output wire       ram256_t0_we,        // Write enable for the RAM256_T0 (Tag RAM 0)
    output wire [7:0] ram256_t0_addr,      // Address for the RAM256_T0 (Tag RAM 0)
    input  wire [7:0] ram256_t0_data,      // Data read from the RAM256_T0 (Tag RAM 0)

    // RAM256_T1 (Tag Memory 1)
    output wire       ram256_t1_we,        // Write enable for the RAM256_T1 (Tag RAM 1)
    output wire [7:0] ram256_t1_addr,      // Address for the RAM256_T1 (Tag RAM 1)
    input  wire [7:0] ram256_t1_data,      // Data read from the RAM256_T1 (Tag RAM 1)

    // RAM512_D0 (Data Memory 0)
    output wire        ram512_d0_we,       // Write enable for the RAM512_D0 (Data RAM 0)
    output wire [8:0]  ram512_d0_addr,     // Address for the RAM512_D0 (Data RAM 0)
    input  wire [15:0] ram512_d0_data,     // Data read from the RAM512_D0 (Data RAM 0)

    // RAM512_D1 (Data Memory 1)
    output wire        ram512_d1_we,       // Write enable for the RAM512_D1 (Data RAM 1)
    output wire [8:0]  ram512_d1_addr,     // Address for the RAM512_D1 (Data RAM 1)
    input  wire [15:0] ram512_d1_data      // Data read from the RAM512_D1 (Data RAM 1)
);
    wire [15:0] data_0;
    wire [15:0] data_1;

     assign data_0=ram512_d0_data;assign data_1=ram512_d1_data;
assign l1b_data=l1b_addr[0]?{data_0,data_1}:{data_1,data_0};


    localparam TAG_BITS = 8;
    localparam ADR_BITS = 9;

    localparam IDLE      = 3'd0,
               READMEM0  = 3'd1,
               READMEM1  = 3'd2,
               READCACHE = 3'd3;

    reg [2:0] state, next_state;
    reg [ADR_BITS-1:0] addr_0, addr_1;
    reg write_enable;

    wire [ADR_BITS-1:0] data_addr_0 = l1b_addr[17:9] + {{8{1'b0}}, l1b_addr[0]};
    wire [ADR_BITS-1:0] data_addr_1 = l1b_addr[17:9];

    wire valid_0, valid_1;
    wire [TAG_BITS-1:0] tag_0, tag_1;

    wire data_0_ready = (l1b_addr[17:9] == tag_0) && valid_0;
    wire data_1_ready = (l1b_addr[17:9] == tag_1) && valid_1;


    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            write_enable <= 1'b0;
            addr_0 <= {ADR_BITS{1'b0}};
            addr_1 <= {ADR_BITS{1'b0}};
        end else begin
            if ((state == READMEM0 || state == READMEM1) && io_mem_ready) begin
                write_enable <= 1'b1;
            end else begin 
                write_enable <= 1'b0;
            end
            state <= next_state;
            addr_0 <= data_addr_0;
            addr_1 <= data_addr_1;
        end
    end

    always @*begin next_state=state;case(state)
IDLE:if(!data_0_ready)next_state=READMEM0;else if(!data_1_ready)next_state=READMEM1;
READMEM0:if(io_mem_ready)next_state=READMEM1;
READMEM1:if(io_mem_ready)next_state=READCACHE;
READCACHE:next_state=IDLE;default:next_state=IDLE;endcase end
    always @*begin io_mem_valid=(state==READMEM0||state==READMEM1);l1b_wait=state!=IDLE||!data_0_ready||!data_1_ready;io_mem_addr=l1b_addr[17:1];if(state==READMEM1)io_mem_addr=(l1b_addr[17:1]+l1b_addr[0]);end


assign ram512_d0_addr=data_addr_0;assign ram512_d1_addr=data_addr_1;
assign ram512_d0_we=(state==READMEM0)&&io_mem_ready;assign ram512_d1_we=(state==READMEM1)&&io_mem_ready;
    tag_controller tag_ctrl (
        .clk(clk),
        .rst(rst),
        .write_enable(write_enable),
        .write_addr(io_mem_addr[ADR_BITS-1:0]),
        .data_0_out({valid_0, tag_0}),
        .read_addr_0(data_addr_0[7:0]),
        .data_1_out({valid_1, tag_1}),
        .read_addr_1(data_addr_1[7:0]),
        .ram_t0_we(ram256_t0_we),
        .ram_t0_addr(ram256_t0_addr),
        .ram_t0_data(ram256_t0_data),
        .ram_t1_we(ram256_t1_we),
        .ram_t1_addr(ram256_t1_addr),
        .ram_t1_data(ram256_t1_data)
    );

endmodule


module tag_controller (
   input wire clk,                     // Clock signal
   input wire rst,                     // Reset signal

   // Port 0: Write operation (W)
   input wire       write_enable,      // Enable write operation
   input wire [8:0] write_addr,        // Write address (9 bits)

   // Port 0: Read operation for address 0 (R)
   output reg [8:0] data_0_out,        // Data output for read operation on address 0 (9 bits)
   input  wire [7:0] read_addr_0,      // Read address for tag memory 0 (8 bits)

   // Port 1: Read operation for address 1 (R)
   output reg [8:0] data_1_out,        // Data output for read operation on address 1 (9 bits)
   input  wire [7:0] read_addr_1,      // Read address for tag memory 1 (8 bits)

   // RAM256_T0 (Tag Memory 0)
   output reg       ram_t0_we,         // Write enable for the RAM256_T0 (Tag RAM 0)
   output reg [7:0] ram_t0_addr,       // Address for the RAM256_T0 (Tag RAM 0)
   input  wire [7:0] ram_t0_data,      // Data read from the RAM256_T0 (Tag RAM 0)

   // RAM256_T1 (Tag Memory 1)
   output reg       ram_t1_we,         // Write enable for the RAM256_T1 (Tag RAM 1)
   output reg [7:0] ram_t1_addr,       // Address for the RAM256_T1 (Tag RAM 1)
   input  wire [7:0] ram_t1_data       // Data read from the RAM256_T1 (Tag RAM 1)
);
   reg [511:0] RAM;

   wire [7:0] tag_0_data;
   wire [7:0] tag_1_data;

   wire [7:0] tag_addr_0 = write_enable ? write_addr[7:0] : read_addr_0;
   wire [7:0] tag_addr_1 = write_enable ? write_addr[7:0] : read_addr_1;

   always @(posedge clk or posedge rst) begin
       if (rst) begin
           RAM <= 0;
       end else if (write_enable) begin
           RAM[write_addr] <= 1'b1;
       end
   end

   assign tag_0_data = ram_t0_data;
   assign tag_1_data = ram_t1_data;

   always @(*) begin
      ram_t0_addr=tag_addr_0;ram_t1_addr=tag_addr_1;
      data_0_out={RAM[{1'b0,read_addr_0}],tag_0_data};data_1_out={RAM[{1'b1,read_addr_1}],tag_1_data};
      ram_t0_we=write_enable&&!write_addr[8];ram_t1_we=write_enable&&write_addr[8];

   end

endmodule

module static_branch_predict(input [31:0] fetch_rdata_i,fetch_pc_i,register_addr_i,input fetch_valid_i,output reg predict_branch_taken_o,output reg [31:0] predict_branch_pc_o);
wire [31:0] instr=fetch_rdata_i;
wire [31:0] imm_j_type={{12{instr[31]}},instr[19:12],instr[20],instr[30:21],1'b0};
wire [31:0] imm_b_type={{19{instr[31]}},instr[31],instr[7],instr[30:25],instr[11:8],1'b0};
wire [31:0] imm_i_type={{20{instr[31]}},instr[31:20]};
always @*begin predict_branch_taken_o=0;predict_branch_pc_o=fetch_pc_i;
case(instr[6:0])7'h6f:begin predict_branch_taken_o=fetch_valid_i;predict_branch_pc_o=fetch_pc_i+imm_j_type;end
7'h67:begin predict_branch_taken_o=fetch_valid_i;predict_branch_pc_o=fetch_pc_i+register_addr_i+imm_i_type;end
7'h63:begin predict_branch_taken_o=fetch_valid_i&&instr[31];predict_branch_pc_o=fetch_pc_i+imm_b_type;end endcase end endmodule

module cvdp_copilot_mem_allocator #(
    parameter SIZE  = 4,
    parameter ADDRW = $clog2(SIZE)
) (
    input  wire             clk,
    input  wire             reset,

    input  wire             acquire_en,    
    output wire [ADDRW-1:0] acquire_addr,      

    input  wire             release_en,
    input  wire [ADDRW-1:0] release_addr,    

    output wire             empty,
    output wire             full    
);
    reg [SIZE-1:0] free_slots, free_slots_n;
    reg [ADDRW-1:0] acquire_addr_r;
    reg empty_r, full_r;    
    wire [ADDRW-1:0] free_index;
    wire full_d;

    /* Leading zero counter instantiation */
    cvdp_leading_zero_cnt #(
        .DATA_WIDTH(SIZE),.REVERSE(1)
        ) free_slots_sel (
            .data   (free_slots_n),
            .leading_zeros  (free_index),
            .all_zeros (full_d)
        ); 
    assign acquire_addr=acquire_addr_r;assign empty=empty_r;assign full=full_r;
always @*begin free_slots_n=free_slots;if(acquire_en&&!full_r)free_slots_n[acquire_addr_r]=0;if(release_en)free_slots_n[release_addr]=1;end
always @(posedge clk)if(reset)begin free_slots<={SIZE{1'b1}};acquire_addr_r<=0;empty_r<=1;full_r<=0;end else begin free_slots<=free_slots_n;acquire_addr_r<=free_index;empty_r<=&free_slots_n;full_r<=full_d;end


endmodule

module cvdp_leading_zero_cnt #(
    parameter DATA_WIDTH = 32,
    parameter REVERSE = 0 
)(
    input  [DATA_WIDTH -1:0] data,
    output  [$clog2(DATA_WIDTH)-1:0] leading_zeros,
    output all_zeros 
);
    localparam NIBBLES_NUM = DATA_WIDTH/4 ; 
    reg [NIBBLES_NUM-1 :0] all_zeros_flag ;
    reg [1:0]  zeros_cnt_per_nibble [NIBBLES_NUM-1 :0]  ;

    genvar i;
    integer k ;
    // Assign data/nibble 
    reg [3:0]  data_per_nibble [NIBBLES_NUM-1 :0]  ;
    generate
        for (i=0; i < NIBBLES_NUM ; i=i+1) begin
            always @* begin
                data_per_nibble[i] = data[(i*4)+3: (i*4)] ;
            end
        end
    endgenerate

    generate
        for (i=0; i < NIBBLES_NUM ; i=i+1) begin
            if (REVERSE) begin
                always @* begin
                        zeros_cnt_per_nibble[i] [1] = ~(data_per_nibble[i][1] | data_per_nibble[i][0]); 
                        zeros_cnt_per_nibble[i] [0] = (~data_per_nibble[i][0]) &
                                                      ((~data_per_nibble[i][2]) | data_per_nibble[i][1]);
                        all_zeros_flag[i] = (data_per_nibble[i] == 4'b0000);
                end
            end else begin
                always @* begin
                    zeros_cnt_per_nibble[NIBBLES_NUM-1-i][1] = ~(data_per_nibble[i][3] | data_per_nibble[i][2]); 
                    zeros_cnt_per_nibble[NIBBLES_NUM-1-i][0] = (~data_per_nibble[i][3]) &
                                     ((~data_per_nibble[i][1]) | data_per_nibble[i][2]);

                    all_zeros_flag[NIBBLES_NUM-1-i] = (data_per_nibble[i] == 4'b0000);
                end
            end
        end
    endgenerate



    reg [$clog2(NIBBLES_NUM)-1:0] index ; 
    reg [1:0]    choosen_nibbles_zeros_count ;
    reg [ $clog2(NIBBLES_NUM*4)-1:0] zeros_count_result ;
    wire [NIBBLES_NUM-1:0]         all_zeros_flag_decoded;

    assign all_zeros_flag_decoded[0] = all_zeros_flag[0] ;
    genvar j;
        generate
            for (j=1; j < NIBBLES_NUM; j=j+1) begin
                assign all_zeros_flag_decoded[j] = all_zeros_flag_decoded[j-1] & all_zeros_flag[j];
            end
        endgenerate

    always@ * begin
        index = 0 ;
        for ( k =0 ; k< NIBBLES_NUM ; k =k +1) begin
            index = index + all_zeros_flag_decoded[k] ;
        end
    end

    always@* begin
        choosen_nibbles_zeros_count = zeros_cnt_per_nibble[index]  ;  
        zeros_count_result = choosen_nibbles_zeros_count + (index <<2) ; 
    end

    assign leading_zeros =  zeros_count_result ;
    assign all_zeros = (data ==0) ;

endmodule

module microcode_sequencer(input clk,c_n_in,c_inc_in,r_en,cc,ien,input [3:0] d_in,input [4:0] instr_in,input oen,output [3:0] d_out,output c_n_out,c_inc_out,full,empty);
